import{_ as i,a0 as l,w as r,s as o,ao as d,I as t,x as n,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"漫談傳統的 Linux 初始化系統的運行級別 | LCTT x X-CMD","titleTemplate":false,"description":"漫談傳統的 Linux 初始化系統的運行級別 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"漫談傳統的 Linux 初始化系統的運行級別 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"漫談傳統的 Linux 初始化系統的運行級別 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170905 Maneuvering around run levels on Linux","title":"漫談傳統的 Linux 初始化系統的運行級別","tag":"201709","desc":""},"relativePath":"201709/20170905 Maneuvering around run levels on Linux.md","filePath":"[post].md"}'),c={name:"201709/20170905 Maneuvering around run levels on Linux.md"};function g(u,s,h,x,k,b){const a=l("Link");return r(),o("div",null,[s[18]||(s[18]=d(`<h1 id="漫談傳統的-linux-初始化系統的運行級別" tabindex="-1">漫談傳統的 Linux 初始化系統的運行級別 <a class="header-anchor" href="#漫談傳統的-linux-初始化系統的運行級別" aria-label="Permalink to “漫談傳統的 Linux 初始化系統的運行級別”">​</a></h1><blockquote><p>瞭解運行級別是如何配置的，如何改變系統運行級別以及修改對應狀態下運行的服務。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2017/09/run-levels-vincent_desjardins-100734685-large.jpg" alt="操作 Linux 的運行級別"></p><p>在 Linux 系統中，<ruby>運行級別<rt>run level</rt></ruby>是指運維的級別，用於描述一種表明什麼服務是可用的系統運行狀態。</p><p>運行級別 1 是嚴格限制的，僅僅用於系統維護；該級別下，網絡連接將不可操作，但是管理員可以通過控制台連接登錄系統。</p><p>其他運行級別的系統允許任何人登錄和使用，但是不同級別中可使用的服務不同。本文將探索如何配置運行級別，如何交互式改變系統運行級別以及修改該狀態下可用的服務。</p><p>Linux 系統的默認運行狀態是一個在系統開機時使用的運行級別（除非有其他的指示），它通常是在 <code>/etc/inittab</code> 文件中進行配置的，該文件內容通常如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id:3:initdefault</span></span></code></pre></div><p>包括 Debian 系統在內的一些系統，默認運行級別為 2，而不是上述文件中的 3，甚至都沒有 <code>/etc/inittab</code> 文件。</p><p>運行級別在默認情況下是如何被配置，其配置依賴於你所運行的 Linux 操作系統的具體發行版本。 例如，在某些系統中， 運行級別 2 是多用户模式，運行級別 3 是多用户模式並支持 NFS （網絡文件系統）。 在另外一些系統，運行級別 2 - 5 基本相同，運行級別 1 是單用户模式。例如，Debian 系統的所用運行級別如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 = 停機</span></span>
<span class="line"><span>1 = 單用户（維護模式）</span></span>
<span class="line"><span>2 = 多用户模式</span></span>
<span class="line"><span>3-5 = 同 2 一樣</span></span>
<span class="line"><span>6 = 重啓</span></span></code></pre></div><p>在 Linux 系統上，運行級別 3 用於共享文件系統給其它系統，可以方便地只通過改變系統的運行級別來啓動和停止文件系統共享。系統從運行級別 2 改變到 3 系統將允許文件系統共享，反之從運行級別 3 改變到 2 則系統不支持文件系統共享。</p><p>在某個運行級別中，系統運行哪些進程依賴於目錄 <code>/etc/rc?.d</code> 目錄的內容，其中 <code>?</code> 可以是 2、 3、 4 或 5 （對應於相應的運行級別）。</p><p>在以下示例中（Ubuntu 系統），由於這些目錄的配置是相同的，我們將看見上述 4 個級別對應的目錄中的內容是一致的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/rc2.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span>
<span class="line"><span>/etc/rc2.d$ cd ../rc3.d</span></span>
<span class="line"><span>/etc/rc3.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span>
<span class="line"><span>/etc/rc3.d$ cd ../rc4.d</span></span>
<span class="line"><span>/etc/rc4.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span>
<span class="line"><span>/etc/rc4.d$ cd ../rc5.d</span></span>
<span class="line"><span>/etc/rc5.d$ ls</span></span>
<span class="line"><span>README         S20smartmontools      S50saned      S99grub-common</span></span>
<span class="line"><span>S20kerneloops  S20speech-dispatcher  S70dns-clean  S99ondemand</span></span>
<span class="line"><span>S20rsync       S20sysstat            S70pppd-dns   S99rc.local</span></span></code></pre></div><p>這些都是什麼文件？它們都是指向 <code>/etc/init.d</code> 目錄下用於啓動服務的腳本符號連接。 這些文件的文件名是至關重要的， 因為它們決定了這些腳本文件的執行順序，例如, S20 腳本是在 S50 腳本前面運行的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 4</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 677 Feb 16  2016 README</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  20 Aug 30 14:40 S20kerneloops -&gt; ../init.d/kerneloops</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 S20rsync -&gt; ../init.d/rsync</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  23 Aug 30 16:10 S20smartmontools -&gt; ../init.d/smartmontools</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  27 Aug 30 14:40 S20speech-dispatcher -&gt; ../init.d/speech-dispatcher</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  17 Aug 31 14:12 S20sysstat -&gt; ../init.d/sysstat</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 S50saned -&gt; ../init.d/saned</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  19 Aug 30 14:40 S70dns-clean -&gt; ../init.d/dns-clean</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S70pppd-dns -&gt; ../init.d/pppd-dns</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  21 Aug 30 14:40 S99grub-common -&gt; ../init.d/grub-common</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S99ondemand -&gt; ../init.d/ondemand</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S99rc.local -&gt; ../init.d/rc.local</span></span></code></pre></div><p>如你所想，目錄 <code>/etc/rc1.d</code> 因運行級別 1 的特殊而不同。它包含的符號鏈接指向非常不同的一套腳本。 同樣也要注意到其中一些腳本以 <code>K</code> 開頭命名，而另一些與其它運行級別腳本一樣以 <code>S</code> 開頭命名。這是因為當系統進入單用户模式時， 一些服務需要<strong>停止</strong>。 然而這些 K 開頭的符號鏈接指向了其它級別 S 開頭的符號鏈接的同一文件時， K（kill）表示這個腳本將以指示其停止的參數執行，而不是以啓動的參數執行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/rc1.d$ ls -l</span></span>
<span class="line"><span>total 4</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  20 Aug 30 14:40 K20kerneloops -&gt; ../init.d/kerneloops</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 K20rsync -&gt; ../init.d/rsync</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  15 Aug 30 14:40 K20saned -&gt; ../init.d/saned</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  23 Aug 30 16:10 K20smartmontools -&gt; ../init.d/smartmontools</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  27 Aug 30 14:40 K20speech-dispatcher -&gt; ../init.d/speech-dispatcher</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 369 Mar 12  2014 README</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  19 Aug 30 14:40 S30killprocs -&gt; ../init.d/killprocs</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  19 Aug 30 14:40 S70dns-clean -&gt; ../init.d/dns-clean</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  18 Aug 30 14:40 S70pppd-dns -&gt; ../init.d/pppd-dns</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root  16 Aug 30 14:40 S90single -&gt; ../init.d/single</span></span></code></pre></div><p>你可以改變系統的默認運行級別，儘管這很少被用到。例如，通過修改前文中提到的 <code>/etc/inittab</code> 文件，你能夠配置 Debian 系統的默認運行級別為 3 （而不是 2），以下是該文件示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id:3:initdefault:</span></span></code></pre></div><p>一旦你修改完成並重啓系統， <code>runlevel</code> 命令將顯示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ runlevel</span></span>
<span class="line"><span>N 3</span></span></code></pre></div><p>另外一種可選方式，使用 <code>init 3</code> 命令，你也能改變系統運行級別（且無需重啓立即生效）， <code>runlevel</code> 命令的輸出為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ runlevel</span></span>
<span class="line"><span>2 3</span></span></code></pre></div><p>當然，除非你修改了系統默認級別的 <code>/etc/rc?.d</code> 目錄下的符號鏈接，使得系統默認運行在一個修改的運行級別之下，否則很少需要通過創建或修改 <code>/etc/inittab</code> 文件改變系統的運行級別。</p><h3 id="在-linux-系統中如何使用運行級別" tabindex="-1">在 Linux 系統中如何使用運行級別？ <a class="header-anchor" href="#在-linux-系統中如何使用運行級別" aria-label="Permalink to “在 Linux 系統中如何使用運行級別？”">​</a></h3><p>為了扼要重述在系統中如何使用運行級別，下面有幾個關於運行級別的快速問答問題：</p><p><strong>如何查詢系統當前的運行級別？</strong></p><p>使用 <code>runlevel</code> 命令。</p><p><strong>如何查看特定運行級別所關聯的服務進程？</strong></p><p>查看與該運行級別關聯的運行級別開始目錄（例如， <code>/etc/rc2.d</code> 對應於運行級別 2）。</p><p><strong>如何查看系統的默認運行級別？</strong></p><p>首先，查看 <code>/etc/inittab</code> 文件是否存在。如果不存在，就執行 <code>runlevel</code> 命令查詢，你一般就已經處在該運行級別。</p><p><strong>如何改變系統運行級別？</strong></p><p>用 <code>init</code> 命令（例如 <code>init 3</code>）臨時改變運行級別，通過修改或創建 <code>/etc/inittab</code> 文件永久改變其運行級別。</p><p><strong>能改變特定運行級別下運行的服務麼？</strong></p><p>當然，通過改變對應的 <code>/etc/rc?.d</code> 目錄下的符號連接即可。</p><p><strong>還有一些其他的什麼需要考慮？</strong></p><p>當改變系統運行級別時，你應該特別小心，確保不影響到系統上正在運行的服務或者正在使用的用户。</p>`,40)),t("p",null,[s[2]||(s[2]=n("（題圖：",-1)),e(a,{href:"https://www.flickr.com/photos/endymion120/4824696883/in/photolist-8mkQi2-8vtyRx-8vvYZS-i31xQj-4TXTS2-S7VRNC-azimYK-dW8cYu-Sb5b7S-S7VRES-fpSVvo-61Zpn8-WxFwGi-UKKq3x-q6NSnC-8vsBLr-S3CPxn-qJUrLr-nDnpNu-8d7a6Q-T7mGpN-RE26wj-SeEXRa-5mZ7LG-Vp7t83-fEG5HS-Vp7sU7-6JpNBi-RCuR8P-qLzCL5-6WsfZx-5nU1tF-6ieGFi-3P5xwh-8mnxpo-hBXwSj-i3iCur-9dmrST-6bXk8d-8vtDb4-i2KLwU-5jhfU6-8vwbrN-ShAtNm-XgzXmb-8rad18-VfXm4L-8tQTrh-Vp7tcb-UceVDB"},{default:p(()=>[...s[0]||(s[0]=[n("Vincent Desjardins",-1)])]),_:1}),s[3]||(s[3]=n()),e(a,{href:"https://creativecommons.org/licenses/by/2.0/legalcode"},{default:p(()=>[...s[1]||(s[1]=[n("(CC BY 2.0)",-1)])]),_:1}),s[4]||(s[4]=n("）",-1))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[6]||(s[6]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3222070/linux/maneuvering-around-run-levels-on-linux.html"},{default:p(()=>[...s[5]||(s[5]=[n("https://www.networkworld.com/article/3222070/linux/maneuvering-around-run-levels-on-linux.html",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[7]||(s[7]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),e(a,{href:"https://github.com/penghuster"},{default:p(()=>[...s[8]||(s[8]=[n("penghuster",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const f=i(c,[["render",g]]);export{S as __pageData,f as default};
